from django.db import migrations


def ages_to_birth_dates(apps, schema_editor):
    """Existing profiles only stored an age; give them a birth date that yields
    the same age today (1 January of the matching year)."""
    Profile = apps.get_model("accounts", "Profile")
    today = datetime.date.today()
    for p in Profile.objects.filter(birth_date__isnull=True):
        p.birth_date = datetime.date(today.year - p.age, 1, 1)
        p.save(update_fields=["birth_date"])


